def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the separator lattice: lines consist almost entirely of the
    # repeated separator color, with occasional marker-color intersections.
    colors = {}
    for row in grid:
        for v in row:
            colors[v] = colors.get(v, 0) + 1
    tile = max(colors, key=colors.get)

    # Identify tile-interior color (the most common color other than the
    # large separator background).
    other = {k: v for k, v in colors.items() if k != tile}
    interior = max(other, key=other.get)

    def line_score_row(r):
        return sum(x == tile for x in grid[r])

    def line_score_col(c):
        return sum(grid[r][c] == tile for r in range(h))

    rowlines = [r for r in range(h) if line_score_row(r) >= w - 2]
    collines = [c for c in range(w) if line_score_col(c) >= h - 2]

    # On crossings, markers replace the separator color. Detect the
    # repeating line spacing from the line coordinates.
    def step(lines):
        ds = [b-a for a, b in zip(lines, lines[1:])]
        if not ds:
            return 1
        from collections import Counter
        return Counter(ds).most_common(1)[0][0]

    dr, dc = step(rowlines), step(collines)
    if not rowlines:
        rowlines = list(range(0, h, dr))
    if not collines:
        collines = list(range(0, w, dc))

    # Keep all but the final boundary line; each crossing represents a
    # cell in the compact marker diagram.
    rowlines = rowlines[:-1]
    collines = collines[:-1]

    out = []
    for r in rowlines:
        row = []
        for c in collines:
            v = grid[r][c]
            row.append(interior if v == tile else v)
        out.append(row)
    return out
