def transform(grid):
    h, w = len(grid), len(grid[0])

    # Separator bands are the rows/columns with mostly one common color;
    # their regularly spaced intersections form the reduced marker grid.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    def band_rows():
        return [r for r in range(h)
                if sum(v == background for v in grid[r]) >= w - 2]

    def band_cols():
        return [c for c in range(w)
                if sum(grid[r][c] == background for r in range(h)) >= h - 2]

    def regular(lines):
        if len(lines) < 2:
            return lines
        from collections import Counter
        step = Counter(b-a for a, b in zip(lines, lines[1:])).most_common(1)[0][0]
        first = lines[0]
        return [x for x in lines if (x-first) % step == 0]

    rows = regular(band_rows())
    cols = regular(band_cols())

    # Each crossing is an output cell. Omit the far boundary where present.
    if len(rows) > 1:
        rows = rows[:-1]
    if len(cols) > 1:
        cols = cols[:-1]

    # The tile fill is the most frequent color other than separator color.
    inner = max((v for v in counts if v != background), key=lambda v: counts[v])
    return [[inner if grid[r][c] == background else grid[r][c] for c in cols]
            for r in rows]
